    fn all_shells(h: &Harness) -> HashSet<LodKey> {
        (1..LEVELS)
            .flat_map(|l| h.mesh_shell(l).into_iter().map(move |c| (l, c)))
            .collect()
    }

    #[test]
    fn at_quiescence_each_level_has_delivered_its_mesh_shell_and_every_mesh_is_fresh() {
        let mut h = harness();
        let (ready, unloaded) = h.lod_settle();
        assert!(unloaded.is_empty());

        // A Chunk is meshed once: nothing but a replacement re-dirties it.
        assert_eq!(ready.len(), all_shells(&h).len());
        let meshes = latest(ready);
        assert_eq!(
            meshes.keys().copied().collect::<HashSet<_>>(),
            all_shells(&h)
        );

        for level in 1..LEVELS {
            let shell = h.mesh_shell(level);
            let meshable: HashSet<ChunkCoord> = shell
                .iter()
                .copied()
                .filter(|&c| h.has_six_neighbours(level, c))
                .collect();
            assert_eq!(
                meshable, shell,
                "level {level} has a shell Chunk without a neighbour"
            );
            assert_eq!(h.delivered_at(level), meshable, "level {level}");

            let mut non_empty = 0;
            for &coord in &shell {
                let mesh = &meshes[&(level, coord)];
                assert!(
                    same_mesh(mesh, &h.fresh_mesh(level, coord)),
                    "level {level} {coord} differs from a fresh mesh"
                );
                non_empty += usize::from(!mesh.is_empty());
            }
            assert!(non_empty > 0, "level {level} had nothing to mesh");
        }
    }

    #[cfg(any(feature = "dev", feature = "profiling"))]
    #[test]
    fn the_dev_report_counts_the_jobs_and_weighs_the_meshes_the_client_holds() {
        let mut h = harness();
        let (ready, _) = h.lod_settle();
        let meshes = latest(ready);
        for level in 1..LEVELS {
            let held = h.held(level).len();
            let times = &h.lod_jobs().times;
            // At least: a replacement adds more.
            assert!(
                times.generate_cost(level).jobs >= held as u64,
                "level {level}"
            );
            let longest = times.generate_cost(level).longest_us;
            assert!(
                longest >= times.generate_cost(level).mean_us,
                "level {level}"
            );
            assert!(times.mesh_cost(level).jobs > 0, "level {level}");

            let expected = meshes
                .iter()
                .filter(|((l, _), _)| *l == level)
                .map(|(_, mesh)| measure::MeshSize::of(mesh))
                .fold(measure::MeshSize::default(), |a, b| a + b);
            let weighed = h.lod_state().mesh_sizes(level);
            assert_eq!(weighed.meshes, expected.meshes, "level {level}");
            assert_eq!(weighed.non_empty, expected.non_empty, "level {level}");
            assert_eq!(weighed.quads, expected.quads, "level {level}");
            assert_eq!(weighed.bytes, expected.bytes, "level {level}");
            assert!(weighed.bytes > 0, "level {level} weighed nothing");

            let varied = h.lod_store().non_uniform(level);
            assert!(varied > 0 && varied < held, "level {level}");
        }
    }

